from pathlib import Path
from lesson_authoring import entry as E
B=[['拉丁 ob / ob-','朝向；在前面；对着；有时加强后面动作']]
OP=B+[['拉丁 oppōnere；古法语 oposer / opposer','把东西放在对面；古法语 poser 受 pōnere 影响，不能简单当作同一词的直线音变'],['中古英语 opposen → oppose','提出相反意见、抵抗']]
F=B+[['拉丁 ob- + -fendere → offendere','对着撞击 → 触犯、伤害、使不快'],['法语 ofendre / offendre → 英语 offend','冒犯、触犯']]
S=B+[['拉丁 obstināre → obstinātus','把意志定住 → 不肯改变；与 stāre“站”相关'],['中古英语 obstinat → obstinate','固执的、顽固的']]
D=B+[['拉丁 dūrus → dūrāre；obdūrāre → obdūrātus','硬 → 使变硬；加强这种硬 → 不肯软化'],['中古英语 obdurat → obdurate','顽固的、冷硬的']]
L=[['拉丁 oblīquus','斜的、侧向的；更早拆分有争议'],['法语 oblique → 英语 oblique','倾斜的 → 不直接的']]
FU=B+[['拉丁 fuscus → fuscāre → obfuscāre','暗 → 使暗 → 遮暗、弄得不清楚']]
def A(h,a,b):return h+[[a,b]]
W=[
E('oppose','英 /əˈpəʊz/；美 /əˈpoʊz/','反对；抵制；与……对抗','别人把一个方案往前推，你站到对面提出阻力：可以用论点、投票或行动反对。','ob- 对着，在 p 前同化成 op-；古法语 opposer 的 poser 接“放置”，与拉丁 oppōnere 的意义混合。',OP,'直接说 oppose the plan，不在动词后多加 to。若用 be opposed to，to 就需要保留。poser 与拉丁 pōnere 的关系有历史混合，不能把每个 -pose 都当成 pōnere 直接变音而来。','oppose a proposal；strongly oppose；oppose doing something。','disagree 是意见不一致；oppose 常更进一步，表明自己反对某事发生或实施。',('Several residents oppose the new road.','几位居民反对修建这条新道路。'),('I oppose changing the rules halfway through the competition.','我反对在比赛进行一半时修改规则。'),sources=['https://www.etymonline.com/word/oppose']),
E('opposition','英 /ˌɒpəˈzɪʃən/；美 /ˌɑːpəˈzɪʃən/','反对；对抗；反对派；对手','反对的动作汇成一种力量，或形成站在另一边的一群人。','拉丁 oppōnere → oppositiō，经古法语 oposicion 借入；与 oppose 对应，但不是英语现造 oppose + -ition。',B+[['拉丁 oppōnere → oppositiō → 古法语 oposicion','放在对面 → 对立、反对'],['中古英语 opposicioun → opposition','反对行为；对立一方']],'opposition to 后接反对对象。the opposition 可指政府的反对党，也可指比赛对手，具体是谁靠语境。天文学还用它描述天体从地球看分处相反方向的“冲”。','opposition to；face opposition；the opposition party。','opponent 是一个对手；opposition 常是反对力量或对方整体。不要把所有持不同意见的人都叫 enemy“敌人”。',('The proposal met strong opposition from local residents.','提议遭到当地居民的强烈反对。'),('The opposition questioned the government’s figures.','反对党质疑了政府公布的数据。')),
E('opposed','英 /əˈpəʊzd/；美 /əˈpoʊzd/','反对的；对立的','把自己的立场放到某事的对面，形成明确的反对态度。','oppose + -ed，过去分词用作形容词。',A(OP,'英语 oppose → opposed','反对 → 持反对立场的'),'be opposed to 后的 to 是介词，后面可接名词或 -ing：opposed to raising prices。as opposed to 则常作对比，意思接近“相对于、而非”，不一定表示情绪上的反感。','be opposed to；diametrically opposed；as opposed to。','I oppose it 与 I am opposed to it 都可表达反对；不能混成 I am oppose it。',('They are opposed to raising the entrance fee.','他们反对提高门票价格。'),('We need practical experience as opposed to theory alone.','我们需要实际经验，而不只是理论。')),
E('opposing','英 /əˈpəʊzɪŋ/；美 /əˈpoʊzɪŋ/','对立的；对抗一方的；相反的','把两方放进同一个场景，它们的方向、目标或立场彼此相对。','oppose + -ing；现在分词和形容词。',A(OP,'英语 oppose → opposing','反对、相对 → 处于对立关系的'),'opposing views 是相反的观点；the opposing team 是对方球队。它常放在名词前；表达某人反对某个方案，be opposed to 通常更合适。','opposing sides；opposing views；opposing forces。','opposing 描述对立关系；opposed 常描述所持态度。opposing views 不表示这些观点一定有一个邪恶。',('The article presents two opposing views on the issue.','文章介绍了对这个问题两种相反的看法。'),('The opposing team scored first.','对方球队率先得分。')),
E('opposable','英 /əˈpəʊzəbəl/；美 /əˈpoʊzəbəl/','能与其他指头相对的；可反对的','用拇指指腹去碰其他手指指腹：它能转到对面配合夹住东西，这就是常见的 opposable thumb。','oppose + -able“能够……的”；这里取“放在对面、与……相对”的意思。',A(OP,'英语 oppose + -able → opposable','能够相对 → 尤指能与其余指头对握'),'描述手足结构时，opposable 说的是能与其他指头相对的运动能力。别把 opposable thumb 译成“反对的拇指”；一般“可反对”义存在，但日常最容易遇到的是解剖描述。','an opposable thumb；opposable digits。','opposing 是正在对立或相对；opposable 的 -able 强调具有这种能力。',('An opposable thumb helps us grip small objects.','能与其他手指对握的拇指帮助我们抓住小物件。'),('The robot’s hand was designed with an opposable thumb.','这只机器手设计了一个能与其余手指对握的拇指。'),sources=['https://www.merriam-webster.com/dictionary/opposable']),
E('offend','/əˈfend/','冒犯；使不快；触犯','原先是撞上某物，后来是碰到了人的感受、社会规则或法律的边界。', 'ob- 对着 + -fendere 撞击 → 拉丁 offendere；经法语进入。',F,'offend someone 是冒犯某人；offend against a principle 是违背原则。可能无意冒犯，也可能故意，因此这个词本身不保证有恶意。','offend someone；be easily offended；offend against。','annoy 是使烦躁；offend 更常碰到尊严、价值观或礼貌边界。不同意某人未必就冒犯了他。',('I did not mean to offend you.','我并不是有意冒犯你。'),('The joke offended several people in the room.','这个笑话让房间里的几个人感到被冒犯了。'),sources=['https://www.etymonline.com/word/offend']),
E('offended','/əˈfendɪd/','感到被冒犯的；生气的','冒犯已经落到这个人的感受上：他觉得自己被轻视、被不尊重或碰到了底线。','offend + -ed，过去分词或形容词；词尾 d 后的 -ed 读 /ɪd/。',A(F,'英语 offend → offended','冒犯 → 感到被冒犯的'),'常说 offended by a remark 或 offended at a suggestion。feel offended 讲的是当事人的感受，并不单凭这个词就判定对方一定有侮辱意图。','feel offended；be offended by；look offended。','offensive 描述使人不快的事物；offended 描述感到不快的人。an offensive remark 与 an offended listener 方向不同。',('She felt offended by his dismissive reply.','他那不以为然的回答让她觉得受到了冒犯。'),('He looked offended when nobody took his suggestion seriously.','没人认真考虑他的建议，他显得很不高兴。'),sources=['https://www.etymonline.com/word/offend']),
E('offender','英 /əˈfendə/；美 /əˈfendər/','违法者；犯错者；造成问题的人或事物','把 offend 的行为落实到责任主体：谁违规、谁惹出问题，谁就是这里的 offender。','offend + -er；中古英语已有 offendour / offender 等形式。',A(F,'中古英语 offendour / offender → offender','触犯者 → 违法者、造成问题者'),'a first offender 是初犯者。非法律场景也能说某个应用是耗电的 worst offender，这时是在拟人化地说它问题最大。','a repeat offender；a first offender；the worst offender。','suspect 是嫌疑人；offender 指实施违规或违法的人，二者不能在未确定事实时随便替换。',('The programme helps former offenders return to work.','这个项目帮助曾经违法的人重返工作岗位。'),('Among the apps on my phone, this game is the worst offender for battery drain.','我手机里的应用中，这个游戏最耗电。')),
E('offence','/əˈfens/','违法行为；冒犯；不悦〔英式拼写〕','一次行为撞上了法律或人的感受：前者是违规违法，后者是冒犯。','拉丁 offensa，offendere 的相关名词，经古法语 offense、英语 offence；与 offense 同词异拼。',B+[['拉丁 offendere → offensa → 古法语 offense','撞击、触犯 → 伤害、冒犯、违法行为'],['中古英语 offence → 英式 offence','保留 c 的常见英式写法']],'commit an offence 是实施违法行为；take offence 是觉得受了冒犯。说 no offence 前后若仍然伤人，这句话并不能自动消除冒犯。','commit an offence；take offence at；cause offence；no offence intended。','offence 是常见英式写法，offense 是常见美式写法；不是一个只指情绪、另一个只指犯罪。',('The museum apologised for any offence caused by the notice.','博物馆为这则告示可能造成的冒犯道歉。'),('He took offence at the suggestion that he had not prepared.','有人暗示他没有做准备，他对此感到不悦。'),sources=['https://www.etymonline.com/word/offense']),
E('offense','通常 /əˈfens/；美式体育义常 /ˈɑːfens/','违法行为；冒犯；进攻或进攻方〔常见美式拼写〕','它既能指对规则或感受的冲撞，也能保留主动攻向对方的方向，用来谈球队的进攻。','与 offence 同源同词；美式拼写常保留 s，体育中发展出进攻方义。',B+[['拉丁 offensa → 古法语 offense → 中古英语 offence','触犯、伤害、攻击'],['现代英语 offense','美式常用拼写；体育可指进攻、进攻阵容']],'美式体育评论说 on offense 或 a strong offense，是在谈进攻，不能译成“球队犯罪”。冒犯、违法义常重读第二音节；美式体育进攻义常重读第一音节。','take offense；a minor offense；on offense；a strong offense。','defense 是防守，offense 是进攻；这对词在体育中相对，并不带有违法与守法的道德对比。',('Please do not take offense at my question.','请别因为我的问题而生气。'),('The team was effective on offense but weak on defense.','这支球队进攻有效，但防守薄弱。'),sources=['https://www.etymonline.com/word/offense','https://en.wiktionary.org/wiki/offense#English']),
E('offensive','/əˈfensɪv/','冒犯的；令人不快的；进攻性的；攻势','向外撞击这条线，一边变成让人不舒服，一边保留为主动进攻；两种常用意思都要认识。','法语 offensif 或中世纪拉丁 offensīvus，接拉丁 offend- / offens-；不是简单把现代 offend 换尾巴。',B+[['拉丁 offendere / offens- → 中世纪拉丁 offensīvus；法语 offensif','触犯、攻击 → 进攻的、使人不快的'],['英语 offensive','冒犯性的；进攻性的；名词攻势']],'offensive language 是冒犯性语言；an offensive strategy 是进攻策略；a military offensive 是一场军事攻势。一个词可以同时涉及攻击与冒犯，具体褒贬靠语境。','offensive language；offensive to；an offensive strategy；launch an offensive。','offensive 与 offended 分别站在造成不快和感到不快的两端。体育中的 offensive 不等于 rude。',('The editor removed an offensive phrase from the article.','编辑删掉了文章中一句冒犯性的表述。'),('The coach adopted a more offensive strategy in the second half.','教练在下半场采用了更积极的进攻策略。'),('The report describes the beginning of the military offensive.','报告描述了军事攻势的开始。'),sources=['https://www.etymonline.com/word/offensive']),
E('obstinate','英 /ˈɒbstɪnət/；美 /ˈɑːbstənət/','固执的；顽固的；难以去除的','脚像钉在原地一样，别人劝、事实变，仍旧不肯挪动立场。','拉丁 obstinātus，接 obstināre“坚定意志、不肯改变”；其中后半与 stāre“站”相关。',S,'常含批评，认为这种坚持缺少弹性。也可修饰 cough、stain 等难以消退的东西，这时不是说它们有思想，而是借“怎么也不肯走”的画面。','an obstinate refusal；an obstinate child；an obstinate stain。','determined 常称赞有决心；obstinate 往往批评不听劝。是否合理是两词常见的语气差别。',('He remained obstinate despite the new evidence.','尽管出现了新证据，他还是固执己见。'),('The cleaner finally removed the obstinate stain.','清洁剂终于去掉了那块顽固污渍。'),sources=['https://www.etymonline.com/word/obstinate']),
E('obstinacy','英 /ˈɒbstɪnəsi/；美 /ˈɑːbstənəsi/','固执；顽固','不肯改变不只是一次动作，而成为一种态度或性情，这个名词把它整体拿出来讨论。','中世纪拉丁 obstinātia 进入中古英语；现代可对应 obstinate 与 -acy，但词史不只是一条英语加后缀路线。',[B[0],['拉丁 obstinātus → 中世纪拉丁 obstinātia','顽固的 → 固执这种性质'],['中古英语 obstinacie → obstinacy','固执、顽固']],'常见 sheer obstinacy，意为纯粹因为固执。它可以解释为什么谈判或合作卡住，语气通常不如 persistence 那样肯定。','sheer obstinacy；out of obstinacy；overcome someone’s obstinacy。','persistence 强调持续努力；obstinacy 强调不肯改变，往往忽略理由。两者可能描述同一行为的不同评价。',('She refused out of sheer obstinacy.','她拒绝了，纯粹是因为固执。'),('His obstinacy made a simple discussion unnecessarily difficult.','他的固执让一场简单的讨论变得无谓地困难。'),sources=['https://www.etymonline.com/word/obstinate']),
E('obstinately','英 /ˈɒbstɪnətli/；美 /ˈɑːbstənətli/','固执地；顽固地','动作持续顶在那里：该改的答案不改，该松动的态度不松动。','obstinate + -ly；形容词变副词。',A(S,'英语 obstinate + -ly → obstinately','固执的 → 以固执的方式'),'可以修饰坚持、拒绝，也可以拟人化描写数字始终居高不下。副词说明动作如何发生，不能直接放在 a 与普通名词之间代替形容词。','obstinately refuse；remain obstinately high；obstinately cling to。','obstinately 通常带不赞同；steadfastly 可以赞扬坚定。别把所有坚持都译成固执。',('He obstinately refused to check the calculation again.','他固执地拒绝重新检查计算。'),('The error rate remained obstinately high.','错误率一直居高不下。')),
E('oblique','英 /əˈbliːk/；美 /oʊˈbliːk/','斜的；间接的；不明说的','路线没有正面过去，而是斜着穿过；说话也可以如此，绕着目标暗示，不直接点名。','可靠来源是拉丁 oblīquus，经法语及拉丁借入。更早是否拆成 ob- 与某个弯曲词根，有争议。',L,'an oblique reference 是间接提及；an oblique angle 是斜角。解剖学里也用来命名走向斜的肌肉。记忆时用“斜着”，词源上则停在确定的拉丁形式，不硬造组成。','an oblique reference；an oblique angle；an oblique approach。','indirect 强调不直接；oblique 更形象地带有斜向、旁敲侧击的感觉。obvious 是明显的，与它不要混淆。',('She made an oblique reference to the earlier disagreement.','她拐弯抹角地提到了先前的分歧。'),('The sunlight struck the wall at an oblique angle.','阳光斜着照在墙上。'),sources=['https://www.etymonline.com/word/oblique']),
E('obliquely','英 /əˈbliːkli/；美 /oʊˈbliːkli/','斜着；间接地','把 oblique 的斜向变成动作方式：可以斜穿画面，也可以绕个弯提到某事。','oblique + -ly；保留原词的两种常用方向。',A(L,'英语 oblique + -ly → obliquely','斜的、不直接的 → 斜着、间接地'),'refer obliquely to 指间接提及；travel obliquely across 指斜着穿过。它本身不等于“含糊不清”，一次间接暗示也可能让听者立刻明白。','refer obliquely to；pass obliquely across；look obliquely。','vaguely 是不清楚地；obliquely 是不正面地。表达可能很明确，却仍只作间接暗示。',('The letter referred obliquely to their financial difficulties.','信中间接提到了他们的财务困难。'),('A narrow beam of light crossed the room obliquely.','一道窄窄的光斜穿过房间。')),
E('obliquity','英 /əˈblɪkwəti/；美 /oʊˈblɪkwəti/','倾斜；倾角；转轴倾角；不正直〔书面旧义〕','把“斜着”变成可以描述、甚至测量的状态：斜了多少，偏离参考方向多少。','拉丁 oblīquitās，经法语 obliquité 借入；与 oblique 相关的名词。',[L[0],['拉丁 oblīquitās → 法语 obliquité → 英语 obliquity','倾斜的性质或角度']],'天文学的 axial obliquity 是天体转轴与轨道平面法线的夹角；法线就是垂直于轨道平面的方向。它不是与轨道平面本身的夹角。旧文里 moral obliquity 则把偏斜借作道德不正。','axial obliquity；changes in obliquity；moral obliquity。','obliquity 是倾斜程度或状态；eccentricity 在轨道语境说轨道形状偏离圆的程度，两者不是同一个量。',('The planet’s obliquity affects how sunlight is distributed through the year.','这颗行星的转轴倾角影响阳光在一年中的分布。'),('The essay criticises the character’s moral obliquity.','这篇文章批评了这个人物的品行不端。'),sources=['https://www.etymonline.com/word/oblique','https://science.nasa.gov/science-research/earth-science/climate-science/milankovitch-orbital-cycles-and-their-role-in-earths-climate/']),
E('obfuscate','英 /ˈɒbfəskeɪt/；美 /ˈɑːbfəskeɪt/','使难懂；混淆；遮掩','像在清楚的东西前面罩一层暗幕，让人看不出关键所在；文字也可以靠复杂术语做到这一点。','拉丁 ob- + fuscāre“使变暗”，接 fuscus“暗”；经拉丁分词形式或法语相关形式借入。',A(FU,'拉丁 obfuscātus；法语相关形式 → 英语 obfuscate','遮暗 → 混淆、使不清楚'),'常带批评，暗示复杂表达在遮掩重点；也可只是描述让理解变难的效果。代码混淆语境指改写代码外观，尽量保持行为，却增加阅读难度。','obfuscate the issue；obfuscate the truth；obfuscate code。','clarify 是让人看清；obfuscate 是让人更难看清。复杂不必然等于混淆，关键是是否掩盖、妨碍理解。',('The long explanation only obfuscated the issue.','那段冗长的解释反而把问题弄得更难懂了。'),('The speaker used technical jargon to obfuscate the simple mistake.','发言者用专业术语掩盖那个简单的错误。'),sources=['https://www.etymonline.com/word/obfuscate','https://en.wiktionary.org/wiki/obfuscate#English']),
E('obfuscation','英 /ˌɒbfəˈskeɪʃən/；美 /ˌɑːbfəˈskeɪʃən/','混淆；使难懂；遮掩','把“罩上暗幕”这件事或结果拿出来说：重点被绕开，读者看了很多话却更难判断。','拉丁 obfuscātiō 进入中古英语 obfuscacioun；名词借入记录早于现代动词用法，不能写成英语动词先造再派生。',A(FU,'拉丁 obfuscātiō → 中古英语 obfuscacioun → obfuscation','使暗、遮蔽 → 混淆、掩饰'),'常与 evasion 并列，批评回答回避重点。也见 code obfuscation。不要把它和加密完全等同：让内容难读与由密钥控制可读性不是一回事。','deliberate obfuscation；a tactic of obfuscation；code obfuscation。','confusion 是混乱或困惑；obfuscation 更关注造成不透明的做法或结果。',('The journalist demanded clarity rather than further obfuscation.','记者要求说清楚，而不是继续含糊遮掩。'),('Obfuscation made the programme harder to read, but it did not change its intended output.','混淆处理让程序更难读，但没有改变其预期输出。'),sources=['https://www.etymonline.com/word/obfuscate','https://en.wiktionary.org/wiki/obfuscation#English']),
E('obdurate','英 /ˈɒbdjʊrət/；美 /ˈɑːbdʊrət/','顽固不化的；不肯让步的；冷硬的','一颗心像被硬化了，理由、请求或别人的处境都很难把它软化。','ob- 加强 + 拉丁 dūrāre“使硬” → obdūrātus，借入英语。',D,'比普通 stubborn 更书面，常用于谈判中死不让步，或对道德劝告与痛苦无动于衷。常用形容词词尾读弱读 /ət/；不要按熟悉的动词 -ate 一律读 /eɪt/。','remain obdurate；an obdurate refusal；an obdurate opponent。','obstinate 着重固执地坚持；obdurate 常多一层硬得劝不动、感化不了的感觉，两者并非绝对互斥。',('The landlord remained obdurate despite repeated requests.','尽管再三请求，房东仍不肯让步。'),('Her appeal failed to soften his obdurate attitude.','她的请求没能软化他那顽固的态度。'),sources=['https://www.etymonline.com/word/obdurate','https://en.wiktionary.org/wiki/obdurate#English']),
E('obduracy','英 /ˈɒbdjʊrəsi/；美 /ˈɑːbdərəsi/','顽固不化；冷硬；不肯让步','把 obdurate 的硬态度当作一个障碍来谈：事情卡住，可能就卡在这种不肯软化上。','obdurate 去掉词尾部分，接 -acy 表性质、状态。',A(D,'英语 obdurate → obduracy','顽固不化的 → 顽固不化这种性质'),'多见于书面讨论，常带批评。也可能从旁观者角度描述某方难以撼动，不一定意味着发脾气或大吵大闹。','sheer obduracy；political obduracy；overcome obduracy。','obstinacy 与它高度重叠；obduracy 往往更书面，别为了背词把两者强行分成互不相交的定义。',('The negotiations stalled because of both sides’ obduracy.','由于双方都不肯让步，谈判陷入停滞。'),('The novel presents his obduracy as a barrier to reconciliation.','小说把他的冷硬固执写成和解的障碍。'),sources=['https://www.merriam-webster.com/dictionary/obduracy']),
E('obduration','参考读法：英 /ˌɒbdjʊˈreɪʃən/；美 /ˌɑːbdʊˈreɪʃən/','心肠硬化；顽固不化〔罕见、旧式〕','在旧文里，把人的心逐渐变硬、拒绝悔改或改变这种过程叫出来。','拉丁 obdūrātiō，接 obdūrāre“使硬”；学术或旧式借词。',[B[0],['拉丁 dūrāre → obdūrāre → obdūrātiō','使硬 → 使变得顽固、心肠硬化'],['英语 obduration','硬化、顽固不化；罕见旧式用法']],'主要用于理解旧文学、宗教或历史文本。普通交流用 stubbornness 或更常见的 obduracy 就够了；不要仅因 -duration 看着熟悉就解释成“持续时间”。','obduration of the heart；a state of obduration。','duration 现代通常是持续多久；obduration 在这里是硬化、顽固。相似的字母不足以直接推出今天的意思。',('The old sermon warns against obduration of the heart.','那篇旧布道文告诫人们不要让心变得顽固冷硬。'),('The historian explains obduration as an older word for hardened resistance.','历史学者解释说，obduration 是表示顽固抗拒的旧词。'),sources=['https://en.wiktionary.org/wiki/obduration#English']),
E('obstreperous','英 /əbˈstrepərəs/；美 /əbˈstrepərəs/','吵闹难管的；喧闹抗拒的','别人想推进一件事，他偏在对面大声吵闹，声音本身就成了阻力。','拉丁 ob- 对着 + strepere“发出噪声” → obstreperus，再借入英语并对应 -ous。',B+[['拉丁 strepere → obstrepere → obstreperus','吵闹 → 大声阻碍、压过别人的声音 → 喧闹的'],['英语 obstreperous','吵闹不驯；抗拒管理']],'常形容吵闹、难以控制的人群或行为，语气明显带批评；也可强调不肯配合而不一定真的很响。它比 lively“活泼”更负面。','an obstreperous crowd；obstreperous behaviour；become obstreperous。','obstinate 可以安静地固执；obstreperous 典型画面是吵闹地顶着来。拼写相近，后半来源不同。',('An obstreperous group at the back kept interrupting the discussion.','后排一群吵闹的人不断打断讨论。'),('The chair struggled to manage the obstreperous meeting.','主席费力维持那场吵闹难控的会议。'),sources=['https://www.etymonline.com/word/obstreperous']),
]
ROOT=dict(id='C0847',meaning='朝向、在前；对着、阻挡；加强',core='OB = TOWARD; AGAINST; IN FRONT',image='先想两个人面对面：可以迎面碰上，也可以站在对面挡路。ob- 从这种空间方向走向反对、冒犯、阻力；有些词里只是加强动作。',intro='拉丁 ob 本是介词，也成为前缀。学习时不要只背一个“反对”：occur 的历史是迎面遇到，offend 是撞上并冒犯，oppose 是放到对面形成反对，obdurate 则加强变硬。这里整理它在多个词族中的作用。',forms='ob- 遇到后面的辅音可同化：p 前成 op-，f 前成 of-，c 前成 oc-；另有 o-、os- 等历史形式。变体必须按具体词源确认，不能见到 of、op 开头就判定是此词根。',branches=[['对立与反对','oppose, opposition, opposed, opposing, opposable'],['撞上规则或感受','offend, offended, offender, offence, offense, offensive'],['站住不改、硬而不化','obstinate, obstinacy, obstinately, obdurate, obduracy, obduration'],['暗下来、吵起来','obfuscate, obfuscation, obstreperous'],['相遇、遗漏与展示的其他词族','occur, occurrence, omit, ostensible, ostensibly, ostentatious, ostentatiously'],['保留远源争议的邻近支线','oblique, obliquely, obliquity']],contrasts='ob- 不是“不”的通用前缀。offensive 与 offended 是冒犯者一侧和感受者一侧；opposition 是反对，obstinacy 是固执。oblique 的拉丁来源确定，但更早拆分未定，本页明确保留这一界限。',practice='You can oppose a proposal without trying to offend its author. Explain your reasons clearly: an oblique hint or deliberate obfuscation will not make the discussion easier.\n\n你可以反对一项提议，而不去冒犯提出它的人。把理由讲清楚：拐弯暗示或故意混淆都不会让讨论更容易。',words=[w['word'] for w in W]+['occur','occurrence','omit','ostensible','ostensibly','ostentatious','ostentatiously'])
